import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val action = IntArray(n) { fs.nextInt() }

    val head = IntArray(n) { -1 }
    val reverseHead = IntArray(n) { -1 }
    val to = IntArray(m)
    val reverseTo = IntArray(m)
    val next = IntArray(m)
    val reverseNext = IntArray(m)

    for (i in 0 until m) {
        val a = fs.nextInt() - 1
        val b = fs.nextInt() - 1

        to[i] = b
        next[i] = head[a]
        head[a] = i

        reverseTo[i] = a
        reverseNext[i] = reverseHead[b]
        reverseHead[b] = i
    }

    val reachableFromAssignment = BooleanArray(n)
    val canReachUseWithoutAssignment = BooleanArray(n)
    val queue = IntArray(n)

    var left = 0
    var right = 0

    for (v in 0 until n) {
        if (action[v] == 1) {
            reachableFromAssignment[v] = true
            queue[right++] = v
        }
    }

    while (left < right) {
        val v = queue[left++]
        var edge = head[v]
        while (edge != -1) {
            val u = to[edge]
            if (!reachableFromAssignment[u]) {
                reachableFromAssignment[u] = true
                queue[right++] = u
            }
            edge = next[edge]
        }
    }

    left = 0
    right = 0

    for (v in 0 until n) {
        if (action[v] == 2) {
            canReachUseWithoutAssignment[v] = true
            queue[right++] = v
        }
    }

    while (left < right) {
        val v = queue[left++]

        if (action[v] == 1) continue

        var edge = reverseHead[v]
        while (edge != -1) {
            val u = reverseTo[edge]
            if (!canReachUseWithoutAssignment[u]) {
                canReachUseWithoutAssignment[u] = true
                queue[right++] = u
            }
            edge = reverseNext[edge]
        }
    }

    val output = StringBuilder()
    for (v in 0 until n) {
        if (reachableFromAssignment[v] && canReachUseWithoutAssignment[v]) {
            output.append('1')
        } else {
            output.append('0')
        }
        if (v + 1 < n) output.append('\n')
    }

    print(output)
}

